INSERT INTO public.blitz_questions(topic,question,options,correct_index,legal_act,article,source_url,explanation,verified) VALUES
('ФКЗ о Правительстве: статус','Для назначения федеральным министром предложен гражданин РФ 29 лет. Какова правовая оценка его кандидатуры?','["Возрастное ограничение для федеральных министров составляет 25 лет","Возрастной ценз устанавливается отдельно регламентом министерства","Требование о достижении 30 лет не соблюдено","Возрастной ценз применяется только к Председателю Правительства"]'::jsonb,2,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 6','https://www.consultant.ru/document/cons_doc_LAW_366950/adc83a0db571f2f9c694108495fd690a29a673fe/','Правовое основание — статья 6 соответствующего нормативного акта; указанное правило применяется к описанной ситуации.',true),
('ФКЗ о Правительстве: ограничения','Член Правительства хочет одновременно управлять коммерческим обществом как предприниматель. Каково общее правило?','["Совмещение допускается при одобрении регионального парламента","Предпринимательская деятельность и управление хозяйствующим субъектом запрещены, кроме установленных законом исключений","Допускается любая деятельность без вознаграждения и уведомления","Запрещено только участие в акционерных обществах с госдолей"]'::jsonb,1,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 6','https://www.consultant.ru/document/cons_doc_LAW_366950/adc83a0db571f2f9c694108495fd690a29a673fe/','Правовое основание — статья 6 соответствующего нормативного акта; указанное правило применяется к описанной ситуации.',true),
('ФКЗ о Правительстве: ограничения','Министру предлагают платную научную работу, не финансируемую исключительно иностранными источниками. Какое правило применимо?','["Научная деятельность в целом относится к исключениям из запрета иной оплачиваемой деятельности","Любая дополнительная оплачиваемая деятельность министра запрещена без исключений","Допускается только работа в коммерческой организации на управленческой должности","Вопрос может решаться исключительно голосованием Совета Федерации"]'::jsonb,0,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 6','https://www.consultant.ru/document/cons_doc_LAW_366950/adc83a0db571f2f9c694108495fd690a29a673fe/','Правовое основание — статья 6 соответствующего нормативного акта; указанное правило применяется к описанной ситуации.',true),
('ФКЗ о Правительстве: ограничения','Супруг члена Правительства сохраняет вклад в иностранном банке за пределами России. Как регулируется этот вопрос?','["Запрет относится только к личным счетам члена Правительства","Запрет касается лишь счетов членов Совета Федерации","Допускается сохранение вкладов после устного уведомления Председателя Правительства","Законный запрет на такие вклады распространяется и на супруга"]'::jsonb,3,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 6','https://www.consultant.ru/document/cons_doc_LAW_366950/adc83a0db571f2f9c694108495fd690a29a673fe/','Правовое основание — статья 6 соответствующего нормативного акта; указанное правило применяется к описанной ситуации.',true),
('ФКЗ о Правительстве: ограничения','Федеральному министру предлагают гонорар за выступление именно в качестве члена Правительства. Как поступить?','["Получить гонорар при отражении дохода в декларации","Получить гонорар с согласия Государственной Думы","Отказаться от гонорара: такое вознаграждение запрещено","Принять гонорар, если мероприятие организовано государственным учреждением"]'::jsonb,2,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 6','https://www.consultant.ru/document/cons_doc_LAW_366950/adc83a0db571f2f9c694108495fd690a29a673fe/','Правовое основание — статья 6 соответствующего нормативного акта; указанное правило применяется к описанной ситуации.',true),
('ФКЗ о Правительстве: конфликт интересов','У министра возникла личная заинтересованность, которая может привести к конфликту интересов. Какова обязанность министра?','["Дождаться фактического имущественного ущерба и только затем сообщить","Сообщить в предусмотренном порядке и принять меры по предотвращению или урегулированию конфликта","Перепоручить решение любому подчинённому без уведомления","Считать конфликт несущественным, если доход пока не получен"]'::jsonb,1,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 6','https://www.consultant.ru/document/cons_doc_LAW_366950/adc83a0db571f2f9c694108495fd690a29a673fe/','Правовое основание — статья 6 соответствующего нормативного акта; указанное правило применяется к описанной ситуации.',true),
('ФКЗ о Правительстве: ограничения','Член Правительства владеет пакетом акций российской компании. Что предусмотрено на время замещения должности?','["Передача ценных бумаг и долей участия в доверительное управление","Обязательная безвозмездная передача акций государству","Автоматическая утрата права собственности на ценные бумаги","Безусловное право лично управлять обществом"]'::jsonb,0,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 6','https://www.consultant.ru/document/cons_doc_LAW_366950/adc83a0db571f2f9c694108495fd690a29a673fe/','Правовое основание — статья 6 соответствующего нормативного акта; указанное правило применяется к описанной ситуации.',true),
('ФКЗ о Правительстве: ограничения','Член Правительства хочет быть представителем частной компании в государственном органе. Каково общее ограничение?','["Запрещено лишь представительство иностранных организаций","Такое представительство свободно после регистрации доверенности","Допустимо в любое время при отсутствии дополнительной оплаты","Быть поверенным или представителем по делам третьих лиц в органах власти запрещено"]'::jsonb,3,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 6','https://www.consultant.ru/document/cons_doc_LAW_366950/adc83a0db571f2f9c694108495fd690a29a673fe/','Правовое основание — статья 6 соответствующего нормативного акта; указанное правило применяется к описанной ситуации.',true),
('ФКЗ о Правительстве: назначение','Кто окончательно назначает Председателя Правительства после утверждения кандидатуры Государственной Думой?','["Председатель Государственной Думы","Совет Федерации большинством голосов","Президент Российской Федерации","Конституционный Суд после проверки кандидатуры"]'::jsonb,2,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 7','https://www.consultant.ru/document/cons_doc_LAW_366950/63a63b6da248d9e28a982b10b4071ae40726ee4f/','Правовое основание — статья 7 соответствующего нормативного акта; указанное правило применяется к описанной ситуации.',true),
('ФКЗ о Правительстве: назначение','Президент вступил в должность. В какой срок в общем порядке представляется кандидатура Председателя Правительства в Государственную Думу?','["Не позднее одного месяца","Не позднее двух недель","Не позднее семи дней во всех случаях","Не позднее трёх месяцев"]'::jsonb,1,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 7','https://www.consultant.ru/document/cons_doc_LAW_366950/63a63b6da248d9e28a982b10b4071ae40726ee4f/','Правовое основание — статья 7 соответствующего нормативного акта; указанное правило применяется к описанной ситуации.',true),
('ФКЗ о Правительстве: назначение','После отклонения Государственной Думой кандидатуры Председателя Правительства Президент намерен вновь внести представление. Каков срок?','["В течение недели со дня отклонения","В течение двух месяцев со дня отклонения","Не ранее следующей парламентской сессии","Только после проведения новых выборов депутатов"]'::jsonb,0,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 7','https://www.consultant.ru/document/cons_doc_LAW_366950/63a63b6da248d9e28a982b10b4071ae40726ee4f/','Правовое основание — статья 7 соответствующего нормативного акта; указанное правило применяется к описанной ситуации.',true),
('ФКЗ о Правительстве: назначение','Сколько времени отведено Государственной Думе для рассмотрения представленной Президентом кандидатуры Председателя Правительства?','["В течение тридцати календарных дней","До окончания текущего финансового года","В течение двух недель после утверждения бюджета","В течение недели со дня внесения представления"]'::jsonb,3,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 7','https://www.consultant.ru/document/cons_doc_LAW_366950/63a63b6da248d9e28a982b10b4071ae40726ee4f/','Правовое основание — статья 7 соответствующего нормативного акта; указанное правило применяется к описанной ситуации.',true),
('ФКЗ о Правительстве: назначение','Президент повторно внёс кандидатуру Председателя Правительства, однажды отклонённую Государственной Думой. Возможно ли это?','["Нет, Президент обязан каждый раз представлять нового человека","Да, но лишь после решения Совета Федерации","Да, закон допускает повторное внесение той же кандидатуры","Нет, повторное внесение требует поправки к Конституции"]'::jsonb,2,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 7','https://www.consultant.ru/document/cons_doc_LAW_366950/63a63b6da248d9e28a982b10b4071ae40726ee4f/','Правовое основание — статья 7 соответствующего нормативного акта; указанное правило применяется к описанной ситуации.',true),
('ФКЗ о Правительстве: назначение','Государственная Дума трижды отклонила представленные кандидатуры Председателя Правительства. Как действует Президент?','["Передаёт полномочие назначения Совету Федерации","Назначает Председателя Правительства без утверждения кандидатуры Государственной Думой","Обязан получить согласие Конституционного Суда","Проводит четвёртое согласование той же кандидатуры в обязательном порядке"]'::jsonb,1,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 7','https://www.consultant.ru/document/cons_doc_LAW_366950/63a63b6da248d9e28a982b10b4071ae40726ee4f/','Правовое основание — статья 7 соответствующего нормативного акта; указанное правило применяется к описанной ситуации.',true),
('ФКЗ о Правительстве: министры','Какова процедура назначения федерального министра, ведающего обороной?','["Президент назначает после консультаций с Советом Федерации","Президент назначает после утверждения Государственной Думой","Совет Федерации назначает без участия Президента","Председатель Правительства назначает своим распоряжением"]'::jsonb,0,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 10','https://www.consultant.ru/document/cons_doc_LAW_366950/dc9c12ac23df68a2e18f2ad867f28a29db19242d/','Правовое основание — статья 10 соответствующего нормативного акта; указанное правило применяется к описанной ситуации.',true),
('ФКЗ о Правительстве: министры','Какова процедура назначения федерального министра экономического развития, не относящегося к специальной категории статьи 10?','["Председатель Правительства назначает после консультаций с Советом Федерации","Президент назначает исключительно после всенародного голосования","Государственная Дума назначает министра своим постановлением","Президент назначает после утверждения кандидатуры Государственной Думой"]'::jsonb,3,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 10','https://www.consultant.ru/document/cons_doc_LAW_366950/dc9c12ac23df68a2e18f2ad867f28a29db19242d/','Правовое основание — статья 10 соответствующего нормативного акта; указанное правило применяется к описанной ситуации.',true),
('ФКЗ о Правительстве: министры','Кто вносит в Совет Федерации представление о кандидатуре министра из специальной категории обороны, безопасности и иностранных дел?','["Председатель Государственной Думы","Генеральный прокурор Российской Федерации","Президент Российской Федерации","Председатель Совета Федерации по собственной инициативе"]'::jsonb,2,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 10','https://www.consultant.ru/document/cons_doc_LAW_366950/dc9c12ac23df68a2e18f2ad867f28a29db19242d/','Правовое основание — статья 10 соответствующего нормативного акта; указанное правило применяется к описанной ситуации.',true),
('ФКЗ о Правительстве: министры','В какой срок Совет Федерации информирует Президента о результатах консультаций по кандидатуре специального федерального министра?','["Не позднее одного месяца после рассмотрения бюджета","Не позднее одной недели после получения представления и материалов","В течение двух месяцев после назначения","Только на первом заседании следующей сессии"]'::jsonb,1,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 10','https://www.consultant.ru/document/cons_doc_LAW_366950/dc9c12ac23df68a2e18f2ad867f28a29db19242d/','Правовое основание — статья 10 соответствующего нормативного акта; указанное правило применяется к описанной ситуации.',true),
('ФКЗ о Правительстве: министры','Кто представляет Государственной Думе кандидатуры федеральных министров, требующих её утверждения?','["Председатель Правительства Российской Федерации","Президент непосредственно без участия Председателя Правительства","Совет Федерации по запросу Правительства","Руководитель соответствующего комитета Государственной Думы"]'::jsonb,0,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 10','https://www.consultant.ru/document/cons_doc_LAW_366950/dc9c12ac23df68a2e18f2ad867f28a29db19242d/','Правовое основание — статья 10 соответствующего нормативного акта; указанное правило применяется к описанной ситуации.',true),
('ФКЗ о Правительстве: законодательство','Какие действия вправе совершать Правительство в рамках права законодательной инициативы?','["Принимать федеральные законы без участия палат парламента","Подписывать принятые законы вместо Президента","Отменять постановления Государственной Думы собственным распоряжением","Вносить законопроекты и поправки к проектам, находящимся в Государственной Думе"]'::jsonb,3,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 26','https://www.consultant.ru/document/cons_doc_LAW_366950/cdb7271a9d0f06babd06f6149ab60ed438e5c0ae/','Правовое основание — статья 26 соответствующего нормативного акта; указанное правило применяется к описанной ситуации.',true),
('ФКЗ о Правительстве: законодательство','Каков общий максимальный срок подготовки письменного заключения Правительства на поступивший законопроект, предусматривающий расходы федерального бюджета?','["Семь дней без возможности продления","Два месяца без возможности продления","Один месяц, с возможностью согласованного продления","Шесть месяцев по решению любого министра"]'::jsonb,2,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 26','https://www.consultant.ru/document/cons_doc_LAW_366950/cdb7271a9d0f06babd06f6149ab60ed438e5c0ae/','Правовое основание — статья 26 соответствующего нормативного акта; указанное правило применяется к описанной ситуации.',true),
('ФКЗ о Правительстве: законодательство','Правительство разрабатывает проект федерального закона по предмету совместного ведения РФ и субъектов. Куда проект должен быть направлен в обязательном порядке?','["Только в федеральные коммерческие банки","В органы государственной власти субъектов Российской Федерации","Только в органы местного самоуправления без участия субъектов","Исключительно в Конституционный Суд до внесения"]'::jsonb,1,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 26','https://www.consultant.ru/document/cons_doc_LAW_366950/cdb7271a9d0f06babd06f6149ab60ed438e5c0ae/','Правовое основание — статья 26 соответствующего нормативного акта; указанное правило применяется к описанной ситуации.',true),
('ФКЗ о Правительстве: законодательство','Кто может официально представлять внесённый Правительством законопроект в палатах Федерального Собрания?','["Назначенный Правительством официальный представитель","Любой служащий по собственной инициативе","Исключительно председатель федерального суда","Только председатель избирательной комиссии"]'::jsonb,0,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 26','https://www.consultant.ru/document/cons_doc_LAW_366950/cdb7271a9d0f06babd06f6149ab60ed438e5c0ae/','Правовое основание — статья 26 соответствующего нормативного акта; указанное правило применяется к описанной ситуации.',true),
('ФКЗ о Правительстве: законодательство','Какая позиция верна для официальных отзывов Правительства на рассматриваемые палатами федеральные законы и законопроекты?','["Они могут существовать только в закрытых архивах Правительства","Они заменяют голосование в Совете Федерации","После отзыва все законопроекты автоматически отклоняются","Такие отзывы подлежат оглашению или распространению при рассмотрении"]'::jsonb,3,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 26','https://www.consultant.ru/document/cons_doc_LAW_366950/cdb7271a9d0f06babd06f6149ab60ed438e5c0ae/','Правовое основание — статья 26 соответствующего нормативного акта; указанное правило применяется к описанной ситуации.',true),
('ФКЗ о Правительстве: заседания','Правительство запланировало заседания раз в два месяца. Соответствует ли это установленной периодичности?','["Да, минимальная частота — одно заседание в квартал","Да, периодичность определяется исключительно Регламентом Совета Федерации","Нет, заседания проводятся не реже одного раза в месяц","Нет, заседания должны проводиться ежедневно"]'::jsonb,2,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 30','https://www.consultant.ru/document/cons_doc_LAW_366950/a816d8d862ae5bbb7a9e14f472821a3b9cd4852e/','Правовое основание — статья 30 соответствующего нормативного акта; указанное правило применяется к описанной ситуации.',true),
('ФКЗ о Правительстве: заседания','Министр не может лично участвовать в заседании Правительства. Что предусматривает ФКЗ?','["Автоматическую замену министра представителем муниципалитета","Уведомление Председателя Правительства о невозможности участия","Письменный отказ от министерской должности","Перенос всего заседания решением министра"]'::jsonb,1,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 30','https://www.consultant.ru/document/cons_doc_LAW_366950/a816d8d862ae5bbb7a9e14f472821a3b9cd4852e/','Правовое основание — статья 30 соответствующего нормативного акта; указанное правило применяется к описанной ситуации.',true),
('ФКЗ о Правительстве: заседания','Может ли представитель Центрального банка участвовать в заседании Правительства в установленном порядке?','["Да, при соблюдении федерального законодательства или правительственного порядка","Нет, участие Центрального банка запрещено","Да, только после избрания депутатом Государственной Думы","Да, автоматически с правом решающего голоса при любом вопросе"]'::jsonb,0,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 30','https://www.consultant.ru/document/cons_doc_LAW_366950/a816d8d862ae5bbb7a9e14f472821a3b9cd4852e/','Правовое основание — статья 30 соответствующего нормативного акта; указанное правило применяется к описанной ситуации.',true),
('ФКЗ о Правительстве: компетенция заседаний','Кабинет предлагает направить проект федерального бюджета в Государственную Думу без решения на заседании Правительства. Допускается ли это?','["Да, если его поддержало Министерство финансов","Да, если вопрос предварительно рассмотрен Президиумом","Да, если проект внесён в электронном виде","Нет, такое решение принимается исключительно на заседании Правительства"]'::jsonb,3,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 31','https://www.consultant.ru/document/cons_doc_LAW_366950/799c3a188002dc18672fb40a34283d5a9a11361d/','Правовое основание — статья 31 соответствующего нормативного акта; указанное правило применяется к описанной ситуации.',true),
('ФКЗ о Правительстве: компетенция заседаний','Правительство принимает решение о внесении собственного законопроекта в Госдуму. Где оно должно быть принято?','["Исключительно на заседании Президиума без участия Правительства","Только в Совете Федерации","На заседании Правительства Российской Федерации","Только руководителем профильного министерства"]'::jsonb,2,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 31','https://www.consultant.ru/document/cons_doc_LAW_366950/799c3a188002dc18672fb40a34283d5a9a11361d/','Правовое основание — статья 31 соответствующего нормативного акта; указанное правило применяется к описанной ситуации.',true),
('ФКЗ о Правительстве: компетенция заседаний','Рассматривается финансовая поддержка в сумме 600 миллионов рублей. Какой порядок рассмотрения предусмотрен ФКЗ о Правительстве?','["Достаточно решения одного федерального министра без заседания","Вопрос подлежит рассмотрению на заседании Правительства","Обязательно обсуждение только в Совете Федерации","Вопрос может рассматриваться лишь при принятии нового федерального бюджета"]'::jsonb,1,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 31','https://www.consultant.ru/document/cons_doc_LAW_366950/799c3a188002dc18672fb40a34283d5a9a11361d/','Правовое основание — статья 31 соответствующего нормативного акта; указанное правило применяется к описанной ситуации.',true),
('ФКЗ о Правительстве: компетенция заседаний','Готовится утверждение Регламента Правительства и Положения об Аппарате. Где осуществляется утверждение?','["На заседании Правительства","На заседании конституционного суда","Только распоряжением руководителя Аппарата","На заседании регионального законодательного органа"]'::jsonb,0,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 31','https://www.consultant.ru/document/cons_doc_LAW_366950/799c3a188002dc18672fb40a34283d5a9a11361d/','Правовое основание — статья 31 соответствующего нормативного акта; указанное правило применяется к описанной ситуации.',true),
('ФКЗ о Правительстве: компетенция заседаний','Кто на заседании Правительства рассматривает ежегодный отчёт о результатах его деятельности, в том числе по вопросам Госдумы?','["Исключительно Советы муниципальных образований","Только избирательные комиссии субъектов","Региональные органы статистики без участия Правительства","Правительство Российской Федерации"]'::jsonb,3,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 31','https://www.consultant.ru/document/cons_doc_LAW_366950/799c3a188002dc18672fb40a34283d5a9a11361d/','Правовое основание — статья 31 соответствующего нормативного акта; указанное правило применяется к описанной ситуации.',true),
('ФКЗ о Правительстве: Президиум','На каком основании может быть образован Президиум Правительства РФ для оперативных вопросов?','["Решением Государственной Думы по инициативе фракций","Постановлением Конституционного Суда","Решением Правительства по предложению Председателя Правительства","Самостоятельным решением главы федерального министерства"]'::jsonb,2,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 32','https://www.consultant.ru/document/cons_doc_LAW_366950/bbd704c77602b6f92826f365357094c1704350e2/','Правовое основание — статья 32 соответствующего нормативного акта; указанное правило применяется к описанной ситуации.',true),
('ФКЗ о Правительстве: Президиум','Какое большинство необходимо для принятия решения Президиума Правительства?','["Большинство от числа участвующих в конкретном заседании","Большинство голосов от общего числа членов Президиума","Не менее двух третей депутатов Госдумы","Единогласное одобрение всеми федеральными министрами"]'::jsonb,1,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 32','https://www.consultant.ru/document/cons_doc_LAW_366950/bbd704c77602b6f92826f365357094c1704350e2/','Правовое основание — статья 32 соответствующего нормативного акта; указанное правило применяется к описанной ситуации.',true),
('ФКЗ о Правительстве: Президиум','Может ли Президиум принять решение, противоречащее акту заседания Правительства?','["Нет, решения Президиума не должны противоречить актам Правительства","Да, Президиум всегда имеет преимущество","Да, при согласии федерального министра финансов","Да, если акт Правительства был принят недавно"]'::jsonb,0,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 32','https://www.consultant.ru/document/cons_doc_LAW_366950/bbd704c77602b6f92826f365357094c1704350e2/','Правовое основание — статья 32 соответствующего нормативного акта; указанное правило применяется к описанной ситуации.',true),
('ФКЗ о Правительстве: Президиум','Кто вправе отменить любое решение Президиума Правительства?','["Только Председатель Государственной Думы","Исключительно Совет Федерации","Любая избирательная комиссия субъекта","Президент Российской Федерации либо Правительство Российской Федерации"]'::jsonb,3,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 32','https://www.consultant.ru/document/cons_doc_LAW_366950/bbd704c77602b6f92826f365357094c1704350e2/','Правовое основание — статья 32 соответствующего нормативного акта; указанное правило применяется к описанной ситуации.',true),
('ФКЗ о Правительстве: сложение полномочий','Перед кем Правительство РФ слагает полномочия в связи с очередными выборами главы государства?','["Перед Государственной Думой предыдущего созыва","Перед Советом Федерации каждые пять лет","Перед вновь избранным Президентом Российской Федерации","Перед Конституционным Судом после любого федерального референдума"]'::jsonb,2,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 34','https://www.consultant.ru/document/cons_doc_LAW_366950/459701175fd6bb3a4e3211f900d465070fa41ae5/','Правовое основание — статья 34 соответствующего нормативного акта; указанное правило применяется к описанной ситуации.',true),
('ФКЗ о Правительстве: сложение полномочий','Каким актом оформляется сложение полномочий Правительства в день вступления нового Президента в должность?','["Федеральным конституционным законом, принятым в тот же день","Распоряжением Правительства Российской Федерации","Постановлением Государственной Думы","Определением Конституционного Суда"]'::jsonb,1,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 34','https://www.consultant.ru/document/cons_doc_LAW_366950/459701175fd6bb3a4e3211f900d465070fa41ae5/','Правовое основание — статья 34 соответствующего нормативного акта; указанное правило применяется к описанной ситуации.',true),
('ФКЗ о Правительстве: отставка','Правительство подало в отставку по собственной инициативе. Кто принимает или отклоняет её?','["Президент Российской Федерации","Государственная Дума большинством от присутствующих","Совет Федерации совместно с Правительством","Генеральный прокурор по согласованию с министром финансов"]'::jsonb,0,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 34','https://www.consultant.ru/document/cons_doc_LAW_366950/459701175fd6bb3a4e3211f900d465070fa41ae5/','Правовое основание — статья 34 соответствующего нормативного акта; указанное правило применяется к описанной ситуации.',true),
('ФКЗ о Правительстве: отставка','После отставки Правительства новый состав ещё не сформирован. Возможно ли продолжение его деятельности?','["Нет, все органы исполнительной власти немедленно прекращают работу","Да, лишь на основании специального федерального референдума","Да, исключительно по решению Совета Федерации","Да, по поручению Президента до формирования нового Правительства"]'::jsonb,3,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 34','https://www.consultant.ru/document/cons_doc_LAW_366950/459701175fd6bb3a4e3211f900d465070fa41ae5/','Правовое основание — статья 34 соответствующего нормативного акта; указанное правило применяется к описанной ситуации.',true),
('ФКЗ о Правительстве: доверие','Какое большинство необходимо для постановления Государственной Думы о недоверии Правительству?','["Большинство от присутствующих при любом кворуме","Не менее трёх четвертей от числа сенаторов","Большинство от общего числа депутатов Государственной Думы","Решение принимается исключительно Председателем Госдумы"]'::jsonb,2,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 35','https://www.consultant.ru/document/cons_doc_LAW_366950/b4aea0591ee8886b268f4f97221ff0ffc9bce5ed/','Правовое основание — статья 35 соответствующего нормативного акта; указанное правило применяется к описанной ситуации.',true),
('ФКЗ о Правительстве: доверие','После первого выражения недоверия Госдумой какой выбор предусмотрен для Президента?','["Немедленно распустить Госдуму без иных вариантов","Объявить отставку Правительства либо не согласиться с решением Госдумы","Передать решение Конституционному Суду как обязательную стадию","Временно запретить заседания Правительства"]'::jsonb,1,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 35','https://www.consultant.ru/document/cons_doc_LAW_366950/b4aea0591ee8886b268f4f97221ff0ffc9bce5ed/','Правовое основание — статья 35 соответствующего нормативного акта; указанное правило применяется к описанной ситуации.',true),
('ФКЗ о Правительстве: доверие','В течение какого времени повторное выражение недоверия Государственной Думой запускает специальный механизм статьи 35?','["В течение трёх месяцев","В течение одной недели","В течение шести месяцев","В течение одного года"]'::jsonb,0,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 35','https://www.consultant.ru/document/cons_doc_LAW_366950/b4aea0591ee8886b268f4f97221ff0ffc9bce5ed/','Правовое основание — статья 35 соответствующего нормативного акта; указанное правило применяется к описанной ситуации.',true),
('ФКЗ о Правительстве: доверие','Председатель Правительства поставил перед Госдумой вопрос о доверии. В какой срок Дума должна рассмотреть его?','["В течение двух месяцев","В течение трёх месяцев","В течение одного финансового года","В течение семи дней"]'::jsonb,3,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 35','https://www.consultant.ru/document/cons_doc_LAW_366950/b4aea0591ee8886b268f4f97221ff0ffc9bce5ed/','Правовое основание — статья 35 соответствующего нормативного акта; указанное правило применяется к описанной ситуации.',true),
('ФЗ № 33-ФЗ: участие граждан','Какой инструмент относится именно к непосредственному осуществлению населением местного самоуправления?','["Общественное обсуждение","Инициативный проект","Местный референдум","Территориальное общественное самоуправление"]'::jsonb,2,'ФЗ от 20.03.2025 № 33-ФЗ «О местном самоуправлении»','статья 42','https://www.consultant.ru/document/cons_doc_LAW_501319/f7628b5d9cb1aa0ea4670cb7762db0207837eb3f/','Правовое основание — статья 42 соответствующего нормативного акта; указанное правило применяется к описанной ситуации.',true),
('ФЗ № 33-ФЗ: участие граждан','Какой из инструментов статьёй 42 отнесён к участию населения, а не к формам непосредственного осуществления?','["Местный референдум","Публичные слушания","Муниципальные выборы","Сход граждан"]'::jsonb,1,'ФЗ от 20.03.2025 № 33-ФЗ «О местном самоуправлении»','статья 42','https://www.consultant.ru/document/cons_doc_LAW_501319/f7628b5d9cb1aa0ea4670cb7762db0207837eb3f/','Правовое основание — статья 42 соответствующего нормативного акта; указанное правило применяется к описанной ситуации.',true),
('ФЗ № 33-ФЗ: участие граждан','Администрация предлагает обязать жителей еженедельно участвовать в бесплатных работах по благоустройству. Какое ограничение нарушается?','["Добровольность и ограничение привлечения не чаще одного раза в три месяца","Только правило о предварительном бюджетном финансировании","Обязанность получать согласие Госдумы","Исключительно правило о численности избирателей"]'::jsonb,0,'ФЗ от 20.03.2025 № 33-ФЗ «О местном самоуправлении»','статья 42','https://www.consultant.ru/document/cons_doc_LAW_501319/f7628b5d9cb1aa0ea4670cb7762db0207837eb3f/','Правовое основание — статья 42 соответствующего нормативного акта; указанное правило применяется к описанной ситуации.',true),
('ФЗ № 33-ФЗ: участие граждан','Какова максимальная продолжительность социально значимых работ при добровольном привлечении совершеннолетних трудоспособных жителей?','["Не более восьми часов подряд","Не более двенадцати часов подряд","Не более шести часов подряд","Не более четырёх часов подряд"]'::jsonb,3,'ФЗ от 20.03.2025 № 33-ФЗ «О местном самоуправлении»','статья 42','https://www.consultant.ru/document/cons_doc_LAW_501319/f7628b5d9cb1aa0ea4670cb7762db0207837eb3f/','Правовое основание — статья 42 соответствующего нормативного акта; указанное правило применяется к описанной ситуации.',true),
('ФЗ № 33-ФЗ: участие граждан','Можно ли относить к социально значимым добровольным работам задания, требующие специальной профессиональной подготовки?','["Да, если работы проводятся муниципалитетом","Да, если работу поручает глава администрации","Нет, допускаются только работы без такой подготовки","Да, при единогласном решении всех депутатов"]'::jsonb,2,'ФЗ от 20.03.2025 № 33-ФЗ «О местном самоуправлении»','статья 42','https://www.consultant.ru/document/cons_doc_LAW_501319/f7628b5d9cb1aa0ea4670cb7762db0207837eb3f/','Правовое основание — статья 42 соответствующего нормативного акта; указанное правило применяется к описанной ситуации.',true)
